# a resource allocation graph is stored as an adjacency list
# graph maps each process or resource node to the nodes it points to
def has_cycle(graph):
    visited = set()
    in_stack = set()

    def dfs(node):
        visited.add(node)
        in_stack.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                if dfs(neighbor):
                    return True
            elif neighbor in in_stack:
                return True
        in_stack.remove(node)
        return False

    return any(dfs(node) for node in graph if node not in visited)

